#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    // +1 at start, -1 at end+1 (end is inclusive); ties put -1 first.
    vector<pair<long long, int>> ev;
    for (int i = 0; i < n; i++) {
        long long s, e;
        scanf("%lld %lld", &s, &e);
        ev.push_back({s, 1});
        ev.push_back({e + 1, -1});
    }
    sort(ev.begin(), ev.end());
    int cur = 0, best = 0;
    for (auto &[t, d] : ev) { cur += d; best = max(best, cur); }
    printf("%d\n", best);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        // Encode each event as time*2 + (0 for -1, 1 for +1) so ties put -1 first.
        long[] ev = new long[2 * n];
        for (int i = 0; i < n; i++) {
            st.nextToken(); long s = (long) st.nval;
            st.nextToken(); long e = (long) st.nval;
            ev[2 * i] = s * 2 + 1;           // start: +1
            ev[2 * i + 1] = (e + 1) * 2;     // end is inclusive: -1 at end+1
        }
        Arrays.sort(ev);
        int cur = 0, best = 0;
        for (long x : ev) { cur += (x & 1) == 1 ? 1 : -1; best = Math.max(best, cur); }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	// Encode each event as time*2 + (0 for -1, 1 for +1) so ties put -1 first.
	ev := make([]int64, 0, 2*n)
	for i := 0; i < n; i++ {
		var s, e int64
		fmt.Fscan(in, &s, &e)
		ev = append(ev, s*2+1, (e+1)*2) // end is inclusive: release at end+1
	}
	slices.Sort(ev)
	cur, best := 0, 0
	for _, x := range ev {
		if x&1 == 1 {
			cur++
		} else {
			cur--
		}
		best = max(best, cur)
	}
	fmt.Println(best)
}
